using System.Reflection;
using System.Linq;

// Check base classes too
var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.9.0/lib/net9.0/Microsoft.Agents.AI.dll");
var sessionType = asm.GetExportedTypes().FirstOrDefault(t => t.Name == "ChatClientAgentSession");
if (sessionType != null) {
    Console.WriteLine($"ChatClientAgentSession base: {sessionType.BaseType?.FullName}");
    Console.WriteLine($"Base assembly: {sessionType.BaseType?.Assembly.Location}");
    // Find constructors of ChatClientAgentSession
    foreach (var c in sessionType.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  CTOR: ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
}

// Check AgentSession from base assembly
var baseAsm = sessionType?.BaseType?.Assembly;
if (baseAsm != null) {
    var agentSessionType = baseAsm.GetExportedTypes().FirstOrDefault(t => t.Name == "AgentSession");
    if (agentSessionType != null) {
        Console.WriteLine($"\nAgentSession from {baseAsm.GetName().Name}:");
        foreach (var c in agentSessionType.GetConstructors(BindingFlags.Public | BindingFlags.Instance))
            Console.WriteLine($"  CTOR: ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
        foreach (var p in agentSessionType.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
            Console.WriteLine($"  PROP: {p.PropertyType.Name} {p.Name}");
    }
}

// Also check AIAgent
var aiAgentType = asm.GetExportedTypes().FirstOrDefault(t => t.Name == "AIAgent");
if (aiAgentType != null) {
    Console.WriteLine($"\nAIAgent is abstract: {aiAgentType.IsAbstract}");
} else {
    // check base types
    var chatAgentType = asm.GetExportedTypes().FirstOrDefault(t => t.Name == "ChatClientAgent");
    Console.WriteLine($"\nChatClientAgent base: {chatAgentType?.BaseType?.FullName}");
    var aiAgentBase = chatAgentType?.BaseType;
    if (aiAgentBase != null) {
        Console.WriteLine($"AIAgent from {aiAgentBase.Assembly.GetName().Name}:");
        foreach (var m in aiAgentBase.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
            Console.WriteLine($"  METHOD: {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    }
}
