using System.Reflection;
using System.Linq;

var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.9.0/lib/net9.0/Microsoft.Agents.AI.dll");

// Check ChatClientAgentSession constructors
var sessionType = asm.GetExportedTypes().First(t => t.Name == "ChatClientAgentSession");
foreach (var c in sessionType.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance))
    Console.WriteLine($"ChatClientAgentSession CTOR: ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))}) [public={c.IsPublic}]");

// Check AIAgentExtensions  
var extType = asm.GetExportedTypes().First(t => t.Name == "AIAgentExtensions");
foreach (var m in extType.GetMethods(BindingFlags.Public | BindingFlags.Static))
    Console.WriteLine($"EXT: {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");

// Check ChatClientAgentSession extensions
var sessExtType = asm.GetExportedTypes().FirstOrDefault(t => t.Name == "ChatClientAgentSession");
Console.WriteLine($"\nChatClientAgentSession methods:");
foreach (var m in sessExtType!.GetMethods(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly))
