using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool implementations -------------------------------------------------

var notebook = new ResearchNotebook();
using var httpClient = new HttpClient();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        [Description("Search the web for information on a query. Returns a list of result snippets.")]
        async (
            [Description("The search query string")] string query,
            CancellationToken cancellationToken) =>
        {
            Console.ForegroundColor = ConsoleColor.DarkCyan;
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            Console.ResetColor();

            try
            {
                // Uses the DuckDuckGo Instant Answer API (no key required)
                var encoded = Uri.EscapeDataString(query);
                var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
                var json = await httpClient.GetFromJsonAsync<JsonElement>(url, cancellationToken);

                var results = new List<string>();

                if (json.TryGetProperty("AbstractText", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
                    results.Add($"[Summary] {abstractText}");

                if (json.TryGetProperty("RelatedTopics", out var topics))
                {
                    foreach (var topic in topics.EnumerateArray().Take(5))
                    {
                        if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                            results.Add($"[Related] {t}");
                    }
                }

                return results.Count > 0
                    ? string.Join("\n", results)
                    : $"No instant results found for \"{query}\". Try rephrasing or breaking down the query.";
            }
            catch (Exception ex)
            {
                return $"Search failed: {ex.Message}. Try a different query.";
            }
        },
        name: "web_search",
        description: "Search the web for information on a query. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        [Description("Save a research note with a title and content for later reference.")]
        (
            [Description("Short title for the note")] string title,
            [Description("The note content / finding")] string content) =>
        {
            notebook.AddNote(title, content);
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            Console.ResetColor();
            return $"Note #{notebook.Count} saved: \"{title}\"";
        },
        name: "save_note",
        description: "Save a research note with a title and content for later reference."),

    AIFunctionFactory.Create(
        [Description("Retrieve all saved research notes.")]
        () =>
        {
            if (notebook.Count == 0)
                return "No notes saved yet.";
            return notebook.Format();
        },
        name: "get_notes",
        description: "Retrieve all saved research notes."),
};

// --- Build the agent ------------------------------------------------------

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

// --- Run the research loop ------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║         🔬 Research Agent                ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var prompt = $"""
        Research the following topic thoroughly:
        "{topic}"

        Instructions:
        1. Use the web_search tool multiple times with different queries to gather information.
        2. Use the save_note tool to record each key finding with a descriptive title.
        3. After gathering enough information (at least 3 searches), use get_notes to review your findings.
        4. Finally, provide a comprehensive summary of your research in your response.
        """;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 50));
    Console.ResetColor();

    try
    {
        var session = await agent.CreateSessionAsync();

        var response = await agent.RunAsync(prompt, session);

        Console.WriteLine();
        Console.ForegroundColor = ConsoleColor.White;
        Console.WriteLine("═══ Research Summary ═══");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

// --- Notebook helper ------------------------------------------------------

internal sealed class ResearchNotebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public int Count => _notes.Count;

    public void AddNote(string title, string content) => _notes.Add((title, content));

    public void Clear() => _notes.Clear();

    public string Format()
    {
        var parts = _notes.Select((n, i) => $"Note #{i + 1} — {n.Title}\n{n.Content}");
        return string.Join("\n\n", parts);
    }
}

