+// --- Build the agent ------------------------------------------------------
+
+IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
+    .GetChatClient(modelId)
+    .AsIChatClient();
+
+var agent = new ChatClientAgent(
+    chatClient,
+    new ChatClientAgentOptions
+    {
+        Name = "ResearchAgent",
+        Description = "An AI agent that researches topics by searching the web and taking notes.",
+        ChatOptions = new ChatOptions
+        {
+            Temperature = 0f,
+            MaxOutputTokens = 2048,
+            Tools = [.. tools],
+        },
+    });
+
+// --- Run the research loop ------------------------------------------------
+
+Console.WriteLine("╔══════════════════════════════════════════╗");
+Console.WriteLine("║         🔬 Research Agent                ║");
+Console.WriteLine("╠══════════════════════════════════════════╣");
+Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
+Console.WriteLine("╚══════════════════════════════════════════╝");
+Console.WriteLine();
+
+while (true)
+{
+    Console.ForegroundColor = ConsoleColor.Green;
+    Console.Write("Topic> ");
+    Console.ResetColor();
+
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
+        break;
+
+    notebook.Clear();
+
+    var prompt = $"""
+        Research the following topic thoroughly:
+        "{topic}"
+
+        Instructions:
+        1. Use the web_search tool multiple times with different queries to gather information.
+        2. Use the save_note tool to record each key finding with a descriptive title.
+        3. After gathering enough information (at least 3 searches), use get_notes to review your findings.
+        4. Finally, provide a comprehensive summary of your research in your response.
+        """;
+
+    Console.WriteLine();
+    Console.ForegroundColor = ConsoleColor.Cyan;
+    Console.WriteLine($"Researching: {topic}");
+    Console.WriteLine(new string('─', 50));
+    Console.ResetColor();
+
+    try
+    {
+        var session = await agent.CreateSessionAsync();
+
+        var response = await agent.RunAsync(prompt, session);
+
+        Console.WriteLine();
+        Console.ForegroundColor = ConsoleColor.White;
+        Console.WriteLine("═══ Research Summary ═══");
+        Console.ResetColor();
+        Console.WriteLine(response.Text);
+        Console.WriteLine();
+    }
+    catch (Exception ex)
+    {
+        Console.ForegroundColor = ConsoleColor.Red;
+        Console.WriteLine($"Error: {ex.Message}");
+        Console.ResetColor();
+    }
+}
+
+Console.WriteLine("Goodbye!");
+
+// --- Notebook helper ------------------------------------------------------
+
+internal sealed class ResearchNotebook
+{
+    private readonly List<(string Title, string Content)> _notes = [];
+
+    public int Count => _notes.Count;
+
+    public void AddNote(string title, string content) => _notes.Add((title, content));
+
+    public void Clear() => _notes.Clear();
+
+    public string Format()
+    {
+        var parts = _notes.Select((n, i) => $"Note #{i + 1} — {n.Title}\n{n.Content}");
+        return string.Join("\n\n", parts);
+    }
+}
